use verus::prelude::*;

verus! {
    /// Given a non‐empty array `a` of i8, returns its maximum element,
    /// witnessed at the first occurrence of that maximum.
    fn amax(a: Vec<i8>) -> (result: i8)
        requires
            // precondition: non‐empty array
            a.len() > 0
        ensures
            // there is some index idx where a[idx] == result,
            // every element is ≤ result,
            // and idx is the first place result occurs
            exists |idx: nat|
                idx < a.len() &&
                a[idx] == result &&
                forall |j: nat| j < a.len() ==> a[j] <= result &&
                forall |j: nat| j < idx      ==> a[j] != result
    {
        // we will scan from i = 1 up to a.len(),
        // tracking max = a[max_idx] on [0..i)
        let mut i:       nat = 1;
        let mut max_idx: nat = 0;
        let mut max:     i8  = a[0];

        while i < a.len()
            invariant i <= a.len()
            // max and max_idx refer to some position < i
            invariant max_idx < i
            invariant max == a[max_idx]
            // max is ≥ every a[j] for j < i
            invariant forall |j: nat| j < i ==> a[j] <= max
            // among those j < i, no earlier occurrence of value == max
            invariant forall |j: nat| j < max_idx ==> a[j] != max
            decreases a.len() - i
        {
            if a[i] > max {
                max     = a[i];
                max_idx = i;
            }
            i = i + 1;
        }

        // at this point:
        //   i == a.len(),
        //   max_idx < a.len(),
        //   max == a[max_idx],
        //   ∀j < a.len(): a[j] ≤ max,
        //   ∀j < max_idx: a[j] ≠ max,
        // which exactly matches our post‐condition with idx = max_idx
        result = max;
    }
}